using UnityEngine;
public class FollowTarget : MonoBehaviour {
    [SerializeField] Transform target;
    [SerializeField] Vector3 offset = new Vector3(0, 3, -6);
    [SerializeField] float smoothTime = .2f;
    Vector3 velocity;
    void LateUpdate() { if (target) transform.position = Vector3.SmoothDamp(transform.position, target.position + offset, ref velocity, smoothTime); }
}

