WITH scores(name, points) AS (VALUES ('Luna', 42), ('Rocío', 58), ('Alex', 42))
SELECT name, points, dense_rank() OVER (ORDER BY points DESC) AS rank
FROM scores ORDER BY rank, name;

WITH events(day) AS (VALUES (DATE '2026-11-01'), (DATE '2026-11-18'), (DATE '2026-12-02'))
SELECT date_trunc('month', day)::date AS month, count(*) AS total
FROM events GROUP BY 1 ORDER BY 1;

WITH names(name) AS (VALUES ('RCC'), ('Studio'), ('RCC'))
SELECT name, count(*) AS occurrences
FROM names GROUP BY name HAVING count(*) > 1;

